package com.github.klboke.kkrepo.admin.ui;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Objects;
import org.junit.jupiter.api.Test;

/**
 * Guards the Maven packaging step of the admin console entry document.
 *
 * <p>The document is generated by {@code ui/} (Vite) and its behaviour is covered by the
 * Vitest suite in {@code ui/src/shared/entrypoints.test.ts}. The one thing that cannot be
 * checked from Node is the {@code maven-resources-plugin} filtering that replaces the version
 * placeholder before the document is served, so this test reads the packaged classpath resource.
 */
class AdminUiEntryPointContractTest {

  @Test
  void entryPointKeepsMavenVersionFiltering() throws IOException {
    String index = packagedIndex();

    // maven-resources-plugin filters this document, so the packaged copy carries the
    // resolved version and must no longer contain the raw placeholder.
    assertTrue(index.contains("<meta name=\"kkrepo-version\" content=\""), "version meta tag");
    assertFalse(index.contains("@project.version@"), "unfiltered Maven placeholder");
  }

  private static String packagedIndex() throws IOException {
    try (InputStream stream = AdminUiEntryPointContractTest.class.getResourceAsStream(
        "/META-INF/resources/admin/index.html")) {
      return new String(Objects.requireNonNull(stream).readAllBytes(), StandardCharsets.UTF_8);
    }
  }
}
